diff --git a/s2/shapeindex.go b/s2/shapeindex.go
index 60f7257..c975901 100644
--- a/s2/shapeindex.go
+++ b/s2/shapeindex.go
@@ -15,6 +15,8 @@
 package s2

 import (
+	"fmt"
+	"io"
 	"math"
 	"slices"
 	"sort"
@@ -1540,3 +1542,278 @@ func maxLevelForEdge(edge Edge) int {
 func (s *ShapeIndex) removeShapeInternal(removed *removedShape, allEdges [][]faceEdge, t *tracker) {
 	// TODO(roberts): finish the implementation of this.
 }
+
+const (
+	shapeIndexEncodingVersion = int8(1)
+	maxEncodedShapes          = 100000000
+	maxEncodedCells           = 100000000
+	maxClippedShapesPerCell   = 100000000
+	maxEdgesPerClippedShape   = 100000000
+)
+
+// Encode encodes the ShapeIndex to the given writer.
+func (s *ShapeIndex) Encode(w io.Writer) error {
+	s.maybeApplyUpdates()
+
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+
+	e := &encoder{w: w}
+
+	// Write header
+	e.writeInt8(shapeIndexEncodingVersion)
+	e.writeUint32(uint32(s.maxEdgesPerCell))
+	e.writeInt32(s.nextID)
+
+	// Write shapes map
+	// Sort keys for deterministic output
+	shapeIDs := make([]int32, 0, len(s.shapes))
+	for id := range s.shapes {
+		shapeIDs = append(shapeIDs, id)
+	}
+	slices.Sort(shapeIDs)
+
+	e.writeUvarint(uint64(len(shapeIDs)))
+	for _, id := range shapeIDs {
+		shape := s.shapes[id]
+		tag := shape.typeTag()
+		if tag == typeTagNone {
+			return fmt.Errorf("cannot encode shape ID %d: shape type %T has typeTagNone", id, shape)
+		}
+		e.writeInt32(id)
+		e.writeUint32(uint32(tag))
+
+		switch tag {
+		case typeTagPolygon:
+			if p, ok := shape.(*Polygon); ok {
+				p.encode(e)
+			} else {
+				return fmt.Errorf("shape ID %d with typeTagPolygon is not *Polygon", id)
+			}
+		case typeTagPolyline:
+			if p, ok := shape.(*Polyline); ok {
+				p.encode(e)
+			} else {
+				return fmt.Errorf("shape ID %d with typeTagPolyline is not *Polyline", id)
+			}
+		case typeTagPointVector:
+			if p, ok := shape.(*PointVector); ok {
+				p.encode(e)
+			} else {
+				return fmt.Errorf("shape ID %d with typeTagPointVector is not *PointVector", id)
+			}
+		case typeTagLaxPolyline:
+			if p, ok := shape.(*LaxPolyline); ok {
+				p.encode(e)
+			} else {
+				return fmt.Errorf("shape ID %d with typeTagLaxPolyline is not *LaxPolyline", id)
+			}
+		case typeTagLaxPolygon:
+			if p, ok := shape.(*LaxPolygon); ok {
+				p.encode(e)
+			} else {
+				return fmt.Errorf("shape ID %d with typeTagLaxPolygon is not *LaxPolygon", id)
+			}
+		default:
+			return fmt.Errorf("unsupported shape type tag %d for shape ID %d", tag, id)
+		}
+
+		if e.err != nil {
+			return e.err
+		}
+	}
+
+	// Write spatial cells
+	e.writeUvarint(uint64(len(s.cells)))
+	for _, cellID := range s.cells {
+		cell := s.cellMap[cellID]
+		if cell == nil {
+			return fmt.Errorf("corrupted index: cellMap missing cell %v", cellID)
+		}
+		e.writeUint64(uint64(cellID))
+		e.writeUvarint(uint64(len(cell.shapes)))
+		for _, clipped := range cell.shapes {
+			e.writeInt32(clipped.shapeID)
+			e.writeBool(clipped.containsCenter)
+			e.writeUvarint(uint64(len(clipped.edges)))
+			for _, edgeID := range clipped.edges {
+				e.writeUvarint(uint64(edgeID))
+			}
+		}
+		if e.err != nil {
+			return e.err
+		}
+	}
+
+	return e.err
+}
+
+// Decode decodes the ShapeIndex from the given reader.
+func (s *ShapeIndex) Decode(r io.Reader) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	d := &decoder{r: asByteReader(r)}
+
+	version := d.readInt8()
+	if d.err != nil {
+		return d.err
+	}
+	if version != shapeIndexEncodingVersion {
+		return fmt.Errorf("unsupported ShapeIndex version %d", version)
+	}
+
+	maxEdgesPerCell := d.readUint32()
+	if maxEdgesPerCell == 0 || maxEdgesPerCell > 1000000 {
+		return fmt.Errorf("invalid maxEdgesPerCell %d", maxEdgesPerCell)
+	}
+
+	nextID := d.readInt32()
+	if nextID < 0 {
+		return fmt.Errorf("invalid nextID %d", nextID)
+	}
+
+	numShapes := d.readUvarint()
+	if d.err != nil {
+		return d.err
+	}
+	if numShapes > maxEncodedShapes {
+		return fmt.Errorf("too many shapes (%d; max is %d)", numShapes, maxEncodedShapes)
+	}
+
+	shapes := make(map[int32]Shape, numShapes)
+	for range numShapes {
+		id := d.readInt32()
+		if id < 0 {
+			return fmt.Errorf("invalid shape ID %d", id)
+		}
+		tag := typeTag(d.readUint32())
+		if d.err != nil {
+			return d.err
+		}
+
+		var shape Shape
+		switch tag {
+		case typeTagPolygon:
+			p := new(Polygon)
+			if err := p.Decode(d.r); err != nil {
+				return err
+			}
+			shape = p
+		case typeTagPolyline:
+			p := new(Polyline)
+			if err := p.Decode(d.r); err != nil {
+				return err
+			}
+			shape = p
+		case typeTagPointVector:
+			p := new(PointVector)
+			if err := p.Decode(d.r); err != nil {
+				return err
+			}
+			shape = p
+		case typeTagLaxPolyline:
+			p := new(LaxPolyline)
+			if err := p.Decode(d.r); err != nil {
+				return err
+			}
+			shape = p
+		case typeTagLaxPolygon:
+			p := new(LaxPolygon)
+			if err := p.Decode(d.r); err != nil {
+				return err
+			}
+			shape = p
+		default:
+			return fmt.Errorf("unsupported shape type tag %d", tag)
+		}
+
+		if d.err != nil {
+			return d.err
+		}
+		if shapes[id] != nil {
+			return fmt.Errorf("duplicate shape ID %d", id)
+		}
+		shapes[id] = shape
+		if id >= nextID {
+			nextID = id + 1
+		}
+	}
+
+	numCells := d.readUvarint()
+	if d.err != nil {
+		return d.err
+	}
+	if numCells > maxEncodedCells {
+		return fmt.Errorf("too many index cells (%d; max is %d)", numCells, maxEncodedCells)
+	}
+
+	cellMap := make(map[CellID]*ShapeIndexCell, numCells)
+	cells := make([]CellID, numCells)
+
+	for i := range numCells {
+		cellID := CellID(d.readUint64())
+		if d.err != nil {
+			return d.err
+		}
+
+		numClipped := d.readUvarint()
+		if d.err != nil {
+			return d.err
+		}
+		if numClipped > maxClippedShapesPerCell {
+			return fmt.Errorf("too many clipped shapes in cell (%d; max is %d)", numClipped, maxClippedShapesPerCell)
+		}
+
+		cell := NewShapeIndexCell(int(numClipped))
+		for j := range numClipped {
+			shapeID := d.readInt32()
+			shape := shapes[shapeID]
+			if shape == nil {
+				return fmt.Errorf("cell references missing shape ID %d", shapeID)
+			}
+			containsCenter := d.readBool()
+			numEdges := d.readUvarint()
+			if d.err != nil {
+				return d.err
+			}
+			if numEdges > maxEdgesPerClippedShape {
+				return fmt.Errorf("too many edges in clipped shape (%d; max is %d)", numEdges, maxEdgesPerClippedShape)
+			}
+			numShapeEdges := shape.NumEdges()
+			cs := newClippedShape(shapeID, int(numEdges))
+			cs.containsCenter = containsCenter
+			for e := range numEdges {
+				edgeID := d.readUvarint()
+				if d.err != nil {
+					return d.err
+				}
+				if int(edgeID) >= numShapeEdges {
+					return fmt.Errorf("edge ID %d out of bounds for shape %d with %d edges", edgeID, shapeID, numShapeEdges)
+				}
+				cs.edges[e] = int(edgeID)
+			}
+			cell.shapes[j] = cs
+		}
+
+		if d.err != nil {
+			return d.err
+		}
+		if cellMap[cellID] != nil {
+			return fmt.Errorf("duplicate cell ID %v in index", cellID)
+		}
+		cellMap[cellID] = cell
+		cells[i] = cellID
+	}
+
+	s.shapes = shapes
+	s.maxEdgesPerCell = int(maxEdgesPerCell)
+	s.nextID = nextID
+	s.cellMap = cellMap
+	s.cells = cells
+	s.pendingAdditionsPos = int32(len(s.shapes))
+	s.pendingRemovals = nil
+	atomic.StoreInt32(&s.status, fresh)
+
+	return nil
+}
