+
+func TestShapeIndexEncodeDecodeEmpty(t *testing.T) {
+	index := NewShapeIndex()
+	var buf bytes.Buffer
+	if err := index.Encode(&buf); err != nil {
+		t.Fatalf("Encode failed: %v", err)
+	}
+
+	if buf.Len() == 0 {
+		t.Fatalf("Empty ShapeIndex encoded to empty byte stream, expected non-empty stream")
+	}
+
+	decoded := NewShapeIndex()
+	if err := decoded.Decode(&buf); err != nil {
+		t.Fatalf("Decode failed: %v", err)
+	}
+
+	if decoded.Len() != 0 {
+		t.Errorf("decoded.Len() = %d, want 0", decoded.Len())
+	}
+	if !decoded.IsFresh() {
+		t.Errorf("decoded.IsFresh() = false, want true")
+	}
+
+	it := decoded.Iterator()
+	if !it.Done() {
+		t.Errorf("iterator on empty decoded index should be Done")
+	}
+}
+
+func TestShapeIndexEncodeDecodeWithoutExplicitBuild(t *testing.T) {
+	index := NewShapeIndex()
+
+	p1 := PointFromLatLng(LatLngFromDegrees(10, 20))
+	p2 := PointFromLatLng(LatLngFromDegrees(10, 21))
+	p3 := PointFromLatLng(LatLngFromDegrees(11, 20))
+
+	poly := PolygonFromOrientedLoops([]*Loop{
+		LoopFromPoints([]Point{p1, p2, p3}),
+	})
+	shapeID := index.Add(poly)
+
+	if index.IsFresh() {
+		t.Errorf("index should be stale before Build/Encode")
+	}
+
+	var buf bytes.Buffer
+	if err := index.Encode(&buf); err != nil {
+		t.Fatalf("Encode failed: %v", err)
+	}
+
+	decoded := NewShapeIndex()
+	if err := decoded.Decode(&buf); err != nil {
+		t.Fatalf("Decode failed: %v", err)
+	}
+
+	if !decoded.IsFresh() {
+		t.Errorf("decoded index should be fresh")
+	}
+	if decoded.Len() != 1 {
+		t.Errorf("decoded.Len() = %d, want 1", decoded.Len())
+	}
+	if decoded.Shape(shapeID) == nil {
+		t.Errorf("decoded.Shape(%d) is nil", shapeID)
+	}
+
+	// Verify queries work without Build()
+	it := decoded.Iterator()
+	if it.Done() {
+		t.Errorf("iterator on non-empty decoded index should not be Done")
+	}
+
+	if !it.LocatePoint(p1) {
+		t.Errorf("LocatePoint(%v) failed on decoded index", p1)
+	}
